import io.circe._, io.circe.parser._

case class Order(id: String, total: Long = 0)

implicit val decodeOrder: Decoder[Order] = Decoder.instance { c =>
  for {
    id    <- c.downField("id").as[String]                  // required
    total <- c.downField("total").as[Option[Long]].map(_.getOrElse(0L))
  } yield Order(id, total)                                  // extra keys ignored
}

